using UnityEngine;
namespace SunnyValley {
 public class ValleyHud:MonoBehaviour {
  public ValleyGame Game;GUIStyle text,small,button;int dragging=-1;bool dragPocket;Texture2D white;
  void Styles(){if(text!=null)return;var font=Resources.Load<Font>("Fonts/PressStart2P-Regular");text=new GUIStyle(GUI.skin.label){font=font,fontSize=12,wordWrap=true};text.normal.textColor=new Color(.3f,.19f,.11f);small=new GUIStyle(text){fontSize=10};button=new GUIStyle(GUI.skin.button){font=font,fontSize=11};white=Texture2D.whiteTexture;}
  void Fill(Rect r,Color color){var old=GUI.color;GUI.color=color;GUI.DrawTexture(r,white);GUI.color=old;}
  void Panel(Rect r){Fill(r,new Color(.3f,.19f,.1f));Fill(new Rect(r.x+2,r.y+2,r.width-4,r.height-4),new Color(.77f,.48f,.24f));Fill(new Rect(r.x+6,r.y+6,r.width-12,r.height-12),new Color(.94f,.79f,.54f));}
  void Label(Rect r,string value){GUI.Label(r,value,text);}
  void OnGUI(){if(Game==null||Game.State==null)return;Styles();float scale=Mathf.Max(1,Mathf.Floor(Mathf.Min(Screen.width/1280f,Screen.height/800f)));GUI.matrix=Matrix4x4.TRS(new Vector3((Screen.width-1280*scale)/2,(Screen.height-800*scale)/2,0),Quaternion.identity,Vector3.one*scale);
   Panel(new Rect(1000,16,264,150));int minutes=(int)(Game.State.Save.phase*1440);Label(new Rect(1014,29,240,35),"ДЕНЬ "+Game.State.Save.day+"  "+(minutes/60).ToString("00")+":"+(minutes%60).ToString("00"));Label(new Rect(1014,70,240,75),"ЗДОРОВЬЕ —\n\nЭНЕРГИЯ — / —\n\nСПУТНИК: НЕТ");
   Panel(new Rect(344,706,592,80));for(int i=0;i<9;i++)Slot(new Rect(357+i*64,719,58,54),false,i);
   GUI.Label(new Rect(300,657,700,30),Game.Message,small);GUI.Label(new Rect(350,686,660,20),"TAB ИНВЕНТАРЬ   M КАРТА   ESC МЕНЮ",small);
   if(Game.Backpack){Panel(new Rect(460,270,360,230));Label(new Rect(480,288,320,30),"РЮКЗАК · 6 ЯЧЕЕК");for(int i=0;i<6;i++)Slot(new Rect(481+(i%3)*105,330+(i/3)*76,90,66),true,i);}
   if(Game.Map){Panel(new Rect(240,90,800,610));Label(new Rect(260,108,760,30),"СОЛНЕЧНАЯ ДОЛИНА · SEED "+Game.State.World.seed);Rect area=new Rect(260,150,760,520);foreach(var c in Game.State.World.cells){Color col=TerrainRules.Plane(c)==TerrainPlane.Wall?new Color(.35f,.38f,.34f):c.kind==7?new Color(.28f,.6f,.7f):c.kind==0?new Color(.4f,.6f,.3f):new Color(.69f,.54f,.33f);Fill(new Rect(area.x+c.x*area.width/87,area.y+c.y*area.height/65,area.width/87+1,area.height/65+1),col);}Vector2 p=Game.State.Room=="outside"?Game.player:Game.State.Save.outside.V;Fill(new Rect(area.x+p.x/4176*area.width-3,area.y+p.y/3120*area.height-3,7,7),Color.white);}
   if(Game.Menu){Panel(new Rect(470,230,340,310));Label(new Rect(500,252,280,35),"СОЛНЕЧНАЯ ДОЛИНА");if(GUI.Button(new Rect(500,300,280,40),"ПРОДОЛЖИТЬ",button))Game.Menu=false;if(GUI.Button(new Rect(500,350,280,40),"СОХРАНИТЬ",button))Game.Save();if(GUI.Button(new Rect(500,400,280,40),"ЗАГРУЗИТЬ",button)){Game.Load();Game.Rebuild();Game.Menu=false;}if(GUI.Button(new Rect(500,450,280,40),"ВЫЙТИ",button)){Game.Save();Application.Quit();}}
   if(dragging>=0){var stack=(dragPocket?Game.State.Save.inventory.pocket:Game.State.Save.inventory.hotbar)[dragging];if(stack!=null)GUI.Label(new Rect(Event.current.mousePosition+new Vector2(12,12),new Vector2(220,32)),Name(stack.item)+" ×"+stack.count,small);if(Event.current.type==EventType.MouseUp){dragging=-1;Event.current.Use();}}
  }
  void Slot(Rect r,bool pocket,int index){var slots=pocket?Game.State.Save.inventory.pocket:Game.State.Save.inventory.hotbar;Panel(r);if(!pocket&&Game.Selected==index)Fill(new Rect(r.x+2,r.y+2,r.width-4,3),new Color(.7f,.24f,.15f));var s=slots[index];if(!pocket)GUI.Label(new Rect(r.x+4,r.y+3,20,15),(index+1).ToString(),small);if(s!=null&&s.count>0){GUI.Label(new Rect(r.x+4,r.y+20,r.width-8,25),Name(s.item),small);GUI.Label(new Rect(r.x+5,r.yMax-16,r.width-10,16),s.count.ToString(),small);}var e=Event.current;if(!r.Contains(e.mousePosition))return;if(e.type==EventType.MouseDown&&e.button==0){if(Game.Backpack&&s!=null&&s.count>0){dragging=index;dragPocket=pocket;}else if(!pocket)Game.Selected=index;e.Use();}else if(e.type==EventType.MouseUp&&dragging>=0){Game.State.Save.inventory.Move(dragPocket,dragging,pocket,index);dragging=-1;e.Use();}}
  static string Name(string item){if(item=="wood")return "Дерево";if(string.IsNullOrEmpty(item))return "";string[] p=item.Split(':');if(p.Length<3)return item;switch(p[1]){case "fence":return "Забор";case "bench":return "Верстак";case "torch":return "Факел";case "lamp":return "Фонарь";case "camp":return "Лагерь";default:return "Декор";}}
 }
}
